scan_linter_check.script:
(function(engine) {
    var rule = new global.EcsContext(engine.current).businessRule();
    if (!engine.rootNode || !rule) {
        return;
    }
    var ast = new global.EcsAst(engine.rootNode);
    var hits = new global.EcsBusinessRule(ast, rule).displayQueries();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-BR-003',
        title: 'Display Business Rule runs queries',
        recommendation: 'Keep display Business Rules to setting g_scratchpad from data already on current. Move lookups to an asynchronous GlideAjax call made by a client script only when the data is needed, or cache the result.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
